sp_widget.client_script:
api.controller=function() {

    var c = this;

    c.form = {};

    c.submitting = false;


    c.create = function() {

        if (!c.form.opportunity_title) {

            alert(
                'Please enter the Opportunity Title.'
            );

            return;

        }


        c.submitting = true;


        c.server.get({

            action: 'create',

            form: c.form

        }).then(function(response) {

            c.submitting = false;


            if (response.data.success) {

                alert(
                    response.data.message
                    + '\nOpportunity ID: '
                    + response.data.opportunity_id
                );


                // Go back to dashboard

                window.location.href =
                    '?id=campus360_recruiter_dashboard_new';

            } else {

                alert(
                    'Unable to create opportunity.'
                );

            }

        });

    };


    c.cancel = function() {

        window.history.back();

    };

}

sp_widget.css:
/* =========================================
   CREATE OPPORTUNITY
   ========================================= */

.opportunity-form-container {
  max-width: 900px;
  margin: 30px auto;
  padding: 0 20px;
}


/* HEADER */

.opportunity-form-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  margin-bottom: 20px;
}


.form-eyebrow {
  color: #5b52e8;

  font-size: 10px;
  font-weight: 700;

  letter-spacing: 1px;
}


.opportunity-form-header h1 {
  margin: 6px 0;

  color: #111a4d;

  font-size: 24px;
  font-weight: 600;
}


.opportunity-form-header p {
  margin: 0;

  color: #777b9a;

  font-size: 12px;
}


/* BACK BUTTON */

.back-button {
  border: none;
  background: transparent;

  color: #5b52e8;

  font-size: 12px;
  font-weight: 500;

  cursor: pointer;
}


/* FORM CARD */

.opportunity-form-card {
  padding: 26px;

  background: #ffffff;

  border: 1px solid #e1e3f1;

  border-radius: 12px;

  box-shadow: 0 4px 16px rgba(30, 35, 80, 0.04);
}


/* FORM ROW */

.form-row {
  display: grid;

  grid-template-columns: 1fr 1fr;

  gap: 18px;
}


/* FORM GROUP */

.form-group {
  margin-bottom: 18px;
}


.form-group label {
  display: block;

  margin-bottom: 7px;

  color: #34395d;

  font-size: 11px;
  font-weight: 600;
}


.form-group label span {
  color: #e05a5a;
}


/* INPUT */

.form-control {
  width: 100%;

  min-height: 40px;

  padding: 9px 11px;

  border: 1px solid #dfe1ef;

  border-radius: 7px;

  background: #ffffff;

  color: #1b214d;

  font-size: 12px;

  outline: none;

  box-sizing: border-box;
}


.form-control:focus {
  border-color: #8d85ee;

  box-shadow:
    0 0 0 3px rgba(91, 82, 232, 0.08);
}


textarea.form-control {
  resize: vertical;
}


/* ACTIONS */

.form-actions {
  display: flex;

  justify-content: flex-end;

  gap: 10px;

  padding-top: 8px;

  border-top: 1px solid #eeeeF5;
}


/* CANCEL */

.cancel-button {
  min-width: 90px;

  padding: 9px 16px;

  border: 1px solid #dddff0;

  border-radius: 7px;

  background: #ffffff;

  color: #626782;

  font-size: 11px;

  cursor: pointer;
}


/* PUBLISH */

.publish-button {
  min-width: 170px;

  padding: 9px 16px;

  border: none;

  border-radius: 7px;

  background: #5b52e8;

  color: #ffffff;

  font-size: 11px;
  font-weight: 600;

  cursor: pointer;
}


.publish-button:hover {
  background: #4b42d4;
}


.publish-button:disabled {
  opacity: 0.6;

  cursor: not-allowed;
}


/* RESPONSIVE */

@media (max-width: 700px) {

  .form-row {
    grid-template-columns: 1fr;
  }

  .opportunity-form-header {
    flex-direction: column;
    gap: 12px;
  }

}

sp_widget.script:
(function() {

    data.success = false;

    if (input && input.action == 'create') {

        var opportunity =
            new GlideRecord(
                'x_snc_campus360_placement_opportunity'
            );

        opportunity.initialize();


        // Opportunity ID

        opportunity.opportunity_id =
            'OPP' +
            new GlideDateTime()
                .getNumericValue();


        // Company

        opportunity.company =
            'e9268662acd303107f44b432e349694b';


        // Form fields

        opportunity.opportunity_title =
            input.form.opportunity_title;

        opportunity.opportunity_type =
            input.form.opportunity_type;

        opportunity.location =
            input.form.location;

        opportunity.ctc_stipend =
            input.form.ctc_stipend;

        opportunity.minimum_cgpa =
            input.form.minimum_cgpa;

        opportunity.eligible_branches =
            input.form.eligible_branches;

        opportunity.required_skills =
            input.form.required_skills;

        opportunity.job_description =
            input.form.job_description;


        // Deadline

        if (input.form.application_deadline) {

            opportunity.application_deadline =
                input.form.application_deadline;

        }


        // Status

        opportunity.status = 'Open';


        // Source

        opportunity.opportunity_source = 'TPO';


        var sysId =
            opportunity.insert();


        if (sysId) {

            data.success = true;

            data.message =
                'Placement opportunity created successfully.';

            data.opportunity_id =
                opportunity.getValue(
                    'opportunity_id'
                );

        }

    }

})();
